        <Field label="Pump flow" unit="GPM" value={gpm} onChange={setGpm} testid="turn-gpm" />
        <Select label="Pool type" value={ptype} onChange={setPtype}
                options={[
                  {value: "residential", label: "Residential"},
                  {value: "commercial", label: "Commercial"},
                  {value: "spa", label: "Spa"},
